<?php $pageTitle='Projects'; require 'config.php'; require 'includes/functions.php'; require_role('student');$uid=user()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $stmt=$pdo->prepare('INSERT INTO projects(user_id,title,description,tech_stack,live_link,github_link,status) VALUES(?,?,?,?,?,?,?)');$stmt->execute([$uid,trim($_POST['title']),trim($_POST['description']),trim($_POST['tech_stack']),trim($_POST['live_link']),trim($_POST['github_link']),'unverified']);flash('success','Project added.');header('Location: projects.php');exit;}
$stmt=$pdo->prepare('SELECT * FROM projects WHERE user_id=? ORDER BY created_at DESC');$stmt->execute([$uid]);$projects=$stmt->fetchAll();include 'includes/header.php';?>
<div class="grid two"><div class="card"><h2>Add Project</h2><form method="post"><div class="form-group"><label>Title</label><input name="title" required></div><div class="form-group"><label>Description</label><textarea name="description" required></textarea></div><div class="form-group"><label>Tech Stack</label><input name="tech_stack"></div><div class="form-group"><label>Live Link</label><input name="live_link"></div><div class="form-group"><label>GitHub Link</label><input name="github_link"></div><button class="btn">Add Project</button></form></div><div><h2>Your Portfolio</h2><?php foreach($projects as $p):?><div class="card" style="margin-bottom:14px"><span class="badge <?=$p['status']==='verified'?'':'warn'?>"><?=e($p['status'])?></span><h3><?=e($p['title'])?></h3><p><?=e($p['description'])?></p><p class="muted"><?=e($p['tech_stack'])?></p></div><?php endforeach;?></div></div>
<?php include 'includes/footer.php'; ?>
